  $('board').onmouseover=e=>{ const r=e.target.closest('[data-pid]'); setHighlight(r?+r.dataset.pid:-1); }; $('board').onmouseleave=()=>{ setHighlight(-1); if(!renderer.hybrid) drawMap(); };
